import { fingerprintForPr, formatFingerprint } from './decide.mjs'
import { closeOpenFence, escapeTableCell, GHSA_PATTERN, sanitizeOutsideText } from './sanitize.mjs'

const MAX_BODY_LENGTH = 60000
const MAX_NOTES_LENGTH = 8000
const CUT_NOTE = "Some sections were cut to fit GitHub's size limit."
/** The most commits shown for one package. upstream.mjs also returns no more than this. */
export const MAX_COMMITS = 10
const MS_PER_DAY = 86400000
const SAFE_URL_PATTERN = /^https:\/\/[^\s)<>|]+$/
const GITHUB_ORIGIN_PATTERN = /^https:\/\/(?:www\.)?github\.com\//i
const PARENT_SEGMENT_PATTERN = /(?:^|\/)\.\.(?:\/|$)/
const SEVERITY_ORDER = ['low', 'moderate', 'medium', 'high', 'critical']
const MAJOR_BANNER =
  'Major version: no automated review. Read the release notes and check breaking changes before you merge.'

// When the body is too long, each section type in this order is removed from the last package
// back to the first, until the body fits.
const DROP_ORDER = ['commits', 'notes', 'info']

/**
 * A major bump gets no automated review, so every major PR opens as a draft for a person to check.
 * @returns {boolean}
 */
export function isDraftPr({ pr }) {
  return pr.kind === 'major'
}

/**
 * Builds the full PR body from the bumps of `pr`, in its order, and the fetched details. Text
 * from outside the repo enters the body only through `sanitizeOutsideText`, and outside URLs only
 * through `safeUrl`.
 * @returns {string}
 */
export function renderPrBody({
  pr,
  bumps: prBumps,
  details,
  fixed,
  partly,
  scope,
  severity,
  ref,
  repoUrl,
  runUrl,
  now = new Date(),
}) {
  const head = [
    isDraftPr({ pr }) ? renderMajorBanner({ prBumps, details }) : null,
    renderLeadLine({ fixed, partly, scope, severity }),
    renderTable({ prBumps, details, fixed, partly, ref, repoUrl, now }),
    '---',
  ]
    .filter(Boolean)
    .join('\n\n')

  const packages = prBumps.map((bump) =>
    renderPackageSections({ bump, detail: details[bump.id] ?? {} }),
  )

  const tail = [
    `Generated by audit-dependencies · [workflow run](${runUrl})`,
    formatFingerprint({ fingerprint: fingerprintForPr({ pr, bumps: prBumps }) }),
  ].join('\n')

  return assemble({ head, packages, tail })
}

function assemble({ head, packages, tail }) {
  const compose = ({ keep = packages.length } = {}) => {
    const parts = [head, ...packages.slice(0, keep).map(composePackage).filter(Boolean)]
    if (keep < packages.length) {
      parts.push(CUT_NOTE)
    }
    return `${[...parts, tail].join('\n\n')}\n`
  }

  for (const key of DROP_ORDER) {
    for (let index = packages.length - 1; index >= 0; index--) {
      if (compose().length <= MAX_BODY_LENGTH) {
        return compose()
      }
      packages[index] = { ...packages[index], [key]: null }
    }
  }

  let keep = packages.length
  while (keep > 0 && compose({ keep }).length > MAX_BODY_LENGTH) {
    keep--
  }
  return compose({ keep })
}

function composePackage({ heading, summaryQuote, advisoryLine, info, notes, commits }) {
  return [heading, summaryQuote, advisoryLine, info, notes, commits].filter(Boolean).join('\n\n')
}

function renderMajorBanner({ prBumps, details }) {
  const bump = prBumps.find((candidate) => details[candidate.id]?.notes?.source === 'none')
  if (!bump) {
    return MAJOR_BANNER
  }
  return `${MAJOR_BANNER}\nNo release notes found for ${releaseLineOf({ version: bump.to })}.x.`
}

// Semver treats each minor change in 0.x as breaking, so a 0.x release line is `0.<minor>`.
function releaseLineOf({ version }) {
  const [major, minor] = version.split('.')
  return major === '0' ? `0.${minor}` : major
}

function renderLeadLine({ fixed, partly, scope, severity }) {
  const noun = fixed.length === 1 ? 'advisory' : 'advisories'
  const base = `This PR fixes ${fixed.length} ${noun} (${scope}, ${severity}+).`
  if (partly.length === 0) {
    return base
  }
  const verb = partly.length === 1 ? 'is' : 'are'
  return `${base} ${partly.length} more ${verb} partly fixed.`
}

function renderTable({ prBumps, details, fixed, partly, ref, repoUrl, now }) {
  const header = [
    '| Package | Change | Type | Age | Downloads/wk | Fixes | Affects |',
    '| --- | --- | --- | --- | --- | --- | --- |',
  ]
  const rows = prBumps.map((bump) => {
    const detail = details[bump.id] ?? {}
    const cells = [
      renderPackageCell({ bump, detail }),
      renderChangeCell({ bump, detail }),
      renderType({ bump }),
      renderAge({ publishedAt: detail.packageMeta?.publishedAt, now }),
      formatDownloads({ count: detail.downloads }),
      renderFixesCell({ advisories: detail.advisories ?? [], fixed, partly }),
      renderAffectsCell({ affects: detail.affects, ref, repoUrl }),
    ]
    return `| ${cells.join(' | ')} |`
  })

  return [...header, ...rows].join('\n')
}

function renderPackageCell({ bump, detail }) {
  const name = escapeTableCell({ text: bump.dependency })
  const npmUrl = safeUrl({ url: `https://www.npmjs.com/package/${bump.dependency}` })
  const link = npmUrl ? `[${name}](${npmUrl})` : name
  const source = sourceUrl({ repo: detail.packageMeta?.repo })
  return source ? `${link} ([source](${source}))` : link
}

function renderChangeCell({ bump, detail }) {
  const from = escapeTableCell({ text: bump.fromVersion || bump.from })
  const to = escapeTableCell({ text: bump.to })
  const label = `\`${from}\` → \`${to}\``
  const compare = safeUrl({ url: detail.commits?.compareUrl ?? detail.notes?.links?.compare })
  return compare ? `[${label}](${compare})` : label
}

function renderType({ bump }) {
  if (bump.isMajor) {
    return '**major**'
  }
  const from = parseVersion({ version: bump.fromVersion })
  const to = parseVersion({ version: bump.to })
  if (!from || !to) {
    return 'update'
  }
  return from[2] === to[2] ? 'patch' : 'minor'
}

function renderAge({ publishedAt, now }) {
  const published = Date.parse(publishedAt ?? '')
  if (Number.isNaN(published)) {
    return 'n/a'
  }
  const days = Math.max(0, Math.floor((now.getTime() - published) / MS_PER_DAY))
  return `${days} ${days === 1 ? 'day' : 'days'}`
}

function formatDownloads({ count }) {
  if (typeof count !== 'number') {
    return 'n/a'
  }
  const thousands = Math.round(count / 1e3)
  if (thousands >= 1000) {
    return `${(count / 1e6).toFixed(1)}M`
  }
  if (count >= 1e3) {
    return `${thousands}k`
  }
  return String(count)
}

function renderFixesCell({ advisories, fixed, partly }) {
  const fixedAdvisories = advisories.filter((advisory) => fixed.includes(advisory.ghsa))
  const partlyAdvisories = advisories.filter((advisory) => partly.includes(advisory.ghsa))
  const parts = []

  if (fixedAdvisories.length > 0) {
    const severity = escapeTableCell({
      text: sanitizeOutsideText({
        text: highestSeverity({ advisories: fixedAdvisories }),
        maxLength: 20,
      }),
    })
    parts.push(`${severity} ${shortGhsaLinks({ advisories: fixedAdvisories })}`)
  }
  if (partlyAdvisories.length > 0) {
    parts.push(`partly ${shortGhsaLinks({ advisories: partlyAdvisories })}`)
  }

  return parts.length > 0 ? parts.join('; ') : 'n/a'
}

function renderAffectsCell({ affects, ref, repoUrl }) {
  const link = ({ name, dir }) =>
    `[${escapeTableCell({ text: name })}](${repoUrl}/tree/${ref}/packages/${dir})`
  const direct = (affects?.direct ?? []).map(link)
  const via = (affects?.via ?? []).map(link)

  const lines = []
  if (direct.length > 0) {
    lines.push(direct.join(', '))
  }
  if (via.length > 0) {
    lines.push(`via: ${via.join(', ')}`)
  }
  return lines.length > 0 ? lines.join('<br>') : 'n/a'
}

function renderPackageSections({ bump, detail }) {
  const advisories = detail.advisories ?? []

  return {
    heading: renderHeading({ bump }),
    summaryQuote: renderSummaryQuote({ advisories }),
    advisoryLine: renderAdvisoryLine({ advisories }),
    info: renderInfo({ advisories }),
    notes: renderNotes({ detail }),
    commits: renderCommits({ detail }),
  }
}

function renderHeading({ bump }) {
  return `### ${oneLine({ text: bump.dependency, maxLength: 100 })}`
}

// A `>` line between summaries keeps each one a separate paragraph in the quote block.
function renderSummaryQuote({ advisories }) {
  const summaries = advisories
    .map((advisory) => oneLine({ text: advisory.summary, maxLength: 200 }))
    .filter(Boolean)
  if (summaries.length === 0) {
    return null
  }
  return summaries.map((summary) => `> ${summary}`).join('\n>\n')
}

// Each link carries its own severity and keeps the summary order, so readers can pair them.
function renderAdvisoryLine({ advisories }) {
  if (advisories.length === 0) {
    return null
  }
  return advisories
    .map((advisory) => {
      const link = ghsaLink({ advisory, label: advisory.ghsa })
      const severity = oneLine({ text: advisory.severity, maxLength: 20 })
      return severity ? `${link} · ${severity}` : link
    })
    .join(', ')
}

function renderInfo({ advisories }) {
  if (advisories.length === 0) {
    return null
  }
  const blocks = advisories.map((advisory) => {
    const text = closeOpenFence({
      text: sanitizeOutsideText({ text: advisory.description, maxLength: 4000 }).trim(),
    })
    return advisories.length > 1
      ? `**${oneLine({ text: advisory.ghsa, maxLength: 40 })}**\n\n${text}`
      : text
  })
  return collapsible({
    summary: 'More information',
    content: `${blocks.join('\n\n')}\n\nSource: GitHub Advisory Database (CC-BY 4.0)`,
  })
}

function renderNotes({ detail }) {
  const entries = detail.notes?.entries ?? []
  const links = detail.notes?.links ?? {}
  const parts = []
  let remaining = MAX_NOTES_LENGTH
  let isCut = false

  for (const entry of entries) {
    if (remaining <= 0) {
      isCut = true
      break
    }
    const url = safeUrl({ url: entry.url })
    const version = oneLine({ text: entry.version, maxLength: 40 })
    const title = url ? `[${version}](${url})` : version
    const text = demoteHeadings({
      text: sanitizeOutsideText({ text: entry.text, maxLength: Infinity }),
    }).trim()
    const isTooLong = text.length > remaining
    const kept = isTooLong ? `${text.slice(0, Math.max(0, remaining - 1))}…` : text
    remaining -= kept.length
    isCut = isCut || isTooLong
    parts.push(`${title}\n\n${closeOpenFence({ text: kept })}`)
  }

  const lines = parts.length > 0 ? [parts.join('\n\n')] : ['No release notes found.']
  if (isCut) {
    lines.push('… cut at the per-package cap')
  }

  const linkParts = [
    ['CHANGELOG.md', links.changelog],
    ['releases', links.releases],
    ['compare', links.compare],
  ]
    .map(([label, url]) => ({ label, url: safeUrl({ url }) }))
    .filter(({ url }) => url)
    .map(({ label, url }) => `[${label}](${url})`)
  if (linkParts.length > 0) {
    lines.push(`All versions: ${linkParts.join(' · ')}`)
  }

  return collapsible({ summary: 'Release notes', content: lines.join('\n\n') })
}

function renderCommits({ detail }) {
  const commits = detail.commits
  const lines = []

  if (commits?.repoMoved) {
    const links = (commits.releaseLinks ?? [])
      .map((url) => safeUrl({ url }))
      .filter(Boolean)
      .map((url) => `- ${url}`)
    lines.push('The repository moved; no commit list. Release pages:', '', ...links)
    return collapsible({ summary: 'Commits', content: lines.join('\n') })
  }

  const shown = (commits?.commits ?? [])
    .filter((commit) => /^[0-9a-f]{7,40}$/i.test(commit.sha ?? ''))
    .slice(0, MAX_COMMITS)
  if (shown.length === 0) {
    lines.push('No commits found.')
  }
  for (const commit of shown) {
    const sha = commit.sha.slice(0, 7)
    const commitUrl = safeUrl({ url: commit.url })
    const label = commitUrl ? `[${sha}](${commitUrl})` : sha
    const message = oneLine({ text: String(commit.message ?? '').split('\n')[0], maxLength: 200 })
    lines.push(`- ${label} ${message}`)
  }

  const moreCount = Math.max(commits?.total ?? 0, shown.length) - shown.length
  if (moreCount > 0) {
    const compare = safeUrl({ url: commits?.compareUrl })
    lines.push('', compare ? `${moreCount} more: [compare](${compare})` : `${moreCount} more.`)
  }

  return collapsible({ summary: 'Commits', content: lines.join('\n') })
}

function collapsible({ summary, content }) {
  return `<details><summary>${summary}</summary>\n\n${content}\n\n</details>`
}

function oneLine({ text, maxLength }) {
  return sanitizeOutsideText({ text, maxLength })
    .replace(/\s*\r?\n\s*/g, ' ')
    .trim()
}

function demoteHeadings({ text }) {
  return text.replace(/^#{1,6}[ \t]+(.+)$/gm, '**$1**')
}

function highestSeverity({ advisories }) {
  const ranked = advisories
    .map((advisory) => String(advisory.severity ?? '').toLowerCase())
    .sort((a, b) => SEVERITY_ORDER.indexOf(b) - SEVERITY_ORDER.indexOf(a))
  return ranked[0] ?? ''
}

function shortGhsaLinks({ advisories }) {
  return advisories
    .map((advisory) => ghsaLink({ advisory, label: advisory.ghsa.split('-')[1] ?? advisory.ghsa }))
    .join(', ')
}

function ghsaLink({ advisory, label }) {
  const text = escapeTableCell({ text: sanitizeOutsideText({ text: label, maxLength: 40 }) })
  if (!GHSA_PATTERN.test(advisory.ghsa ?? '')) {
    return text
  }
  return `[${text}](https://github.com/advisories/${advisory.ghsa})`
}

function sourceUrl({ repo }) {
  if (!repo || !/^[\w.-]+$/.test(repo.owner) || !/^[\w.-]+$/.test(repo.name)) {
    return null
  }
  const base = `https://github.com/${repo.owner}/${repo.name}`
  // A `..` segment could point the link at another repo's issue.
  const hasSafeDirectory =
    repo.directory &&
    /^[\w./@-]+$/.test(repo.directory) &&
    !PARENT_SEGMENT_PATTERN.test(repo.directory)
  return safeUrl({ url: hasSafeDirectory ? `${base}/tree/HEAD/${repo.directory}` : base })
}

/**
 * Returns an outside URL that is safe as a Markdown link target, or null. A github.com link to an
 * issue or PR adds a reference event to it, so github.com links go through redirect.github.com.
 */
function safeUrl({ url }) {
  if (typeof url !== 'string' || !SAFE_URL_PATTERN.test(url)) {
    return null
  }
  return url.replace(GITHUB_ORIGIN_PATTERN, 'https://redirect.github.com/')
}

function parseVersion({ version }) {
  return /^(\d+)\.(\d+)\.(\d+)/.exec(version ?? '')
}
